93	pub(crate) fn return_in_generator(checker: &Checker, function_def: &StmtFunctionDef) {
94	    if function_def.name.id == "__await__" {
95	        return;
96	    }
97	
98	    // Async functions are flagged by the `ReturnInGenerator` semantic syntax error.
99	    if function_def.is_async {
100	        return;
101	    }
102	
103	    let mut visitor = ReturnInGeneratorVisitor::default();
104	    visitor.visit_body(&function_def.body);
105	
106	    if visitor.has_yield {
107	        if let Some(return_) = visitor.return_ {
108	            checker.report_diagnostic(ReturnInGenerator, return_);
109	        }
110	    }
111	}
112	
113	#[derive(Default)]
114	struct ReturnInGeneratorVisitor {
115	    return_: Option<TextRange>,
116	    has_yield: bool,
117	}
118	
119	impl Visitor<'_> for ReturnInGeneratorVisitor {
120	    fn visit_stmt(&mut self, stmt: &Stmt) {
121	        match stmt {
122	            Stmt::FunctionDef(_) => {
123	                // Do not recurse into nested functions; they're evaluated separately.
124	            }
125	            Stmt::Return(ast::StmtReturn {
126	                value: Some(_),
127	                range,
128	                node_index: _,
129	            }) => {
130	                self.return_ = Some(*range);
131	                walk_stmt(self, stmt);
132	            }
133	            _ => walk_stmt(self, stmt),
134	        }
135	    }
136	
137	    fn visit_expr(&mut self, expr: &Expr) {
138	        match expr {
139	            Expr::Lambda(_) => {}
140	            Expr::Yield(_) | Expr::YieldFrom(_) => {
141	                self.has_yield = true;
142	            }
143	            _ => walk_expr(self, expr),
144	        }
145	    }
146	}
