53	/// Whether the currently checked `func` is likely to be a Pytest test.
54	///
55	/// A normal Pytest test function is one whose name starts with `test` and is either:
56	///
57	/// * Placed at module-level, or
58	/// * Placed within a class whose name starts with `Test` and does not have an `__init__` method.
59	///
60	/// During test discovery, Pytest respects a few settings which we do not have access to.
61	/// This function is thus prone to both false positives and false negatives.
62	///
63	/// References:
64	/// - [`pytest` documentation: Conventions for Python test discovery](https://docs.pytest.org/en/stable/explanation/goodpractices.html#conventions-for-python-test-discovery)
65	/// - [`pytest` documentation: Changing naming conventions](https://docs.pytest.org/en/stable/example/pythoncollection.html#changing-naming-conventions)
66	pub(crate) fn is_likely_pytest_test(func: &StmtFunctionDef, checker: &Checker) -> bool {
67	    let semantic = checker.semantic();
68	
69	    if !func.name.starts_with("test") {
70	        return false;
71	    }
72	
73	    if semantic.scope_id.is_global() {
74	        return true;
75	    }
76	
77	    let ScopeKind::Class(class) = semantic.current_scope().kind else {
78	        return false;
79	    };
80	
81	    if !class.name.starts_with("Test") {
82	        return false;
83	    }
84	
85	    class.body.iter().all(|stmt| {
86	        let Stmt::FunctionDef(function) = stmt else {
87	            return true;
88	        };
89	
90	        !visibility::is_init(&function.name)
91	    })
92	}
